#include "adpcm_codec.h"
#include <algorithm>
static const int step_table[89]={7,8,9,10,11,12,13,14,16,17,19,21,23,25,28,31,34,37,41,45,50,55,60,66,73,80,88,97,107,118,130,143,157,173,190,209,230,253,279,307,337,371,408,449,494,544,598,658,724,796,876,963,1060,1166,1282,1411,1552,1707,1878,2066,2272,2499,2749,3024,3327,3660,4026,4428,4871,5358,5894,6484,7132,7845,8630,9493,10442,11487,12635,13899,15289,16818,18500,20350,22385,24623,27086,29794,32767};
static const int idx_table[16]={-1,-1,-1,-1,2,4,6,8,-1,-1,-1,-1,2,4,6,8};
size_t adpcm_encode_frame(const int16_t* p,size_t n,uint8_t* o,int16_t* pred,int* idx){int pr=p[0],ix=*idx; o[0]=0; size_t k=1; uint8_t pack=0; for(size_t i=1;i<n;i++){int step=step_table[ix],d=p[i]-pr,code=0;if(d<0){code=8;d=-d;} int q=step>>3;if(d>=step){code|=4;d-=step;} if(d>=step>>1){code|=2;d-=step>>1;} if(d>=step>>2)code|=1; int delta=step>>3;if(code&4)delta+=step;if(code&2)delta+=step>>1;if(code&1)delta+=step>>2;pr += (code&8)?-delta:delta;pr=std::clamp(pr,-32768,32767);ix=std::clamp(ix+idx_table[code],0,88);if(i&1) o[k++]=pack|(code<<4); else pack=code;} *pred=pr;*idx=ix;return k;}
void adpcm_decode_frame(const uint8_t* in,size_t bytes,int16_t pr,int ix,int16_t* out,size_t n){if(!n)return;out[0]=pr;size_t j=1;for(size_t i=1;i<n;i++){uint8_t c=(i&1)?in[(i/2)+1]>>4:in[(i/2)+1]&15;int step=step_table[ix],d=step>>3;if(c&4)d+=step;if(c&2)d+=step>>1;if(c&1)d+=step>>2;pr+=(c&8)?-d:d;pr=std::clamp(pr,-32768,32767);ix=std::clamp(ix+idx_table[c],0,88);out[j++]=pr;}}
